    int nv = primvertexcount(0, pr);
    for (int i = 0; i < nv; i++) {
        int h = vertexhedge(0, vertexindex(0, pr, i));
        if (hedge_nextequiv(0, h) == h) {
            start = h;
            break;
        }
    }
}
int loop[];
int h = start;
while (h >= 0) {
    push(loop, hedge_srcpoint(0, h));
    int dst = hedge_dstpoint(0, h);
    int nxt = -1;
    for (int c = pointhedge(0, dst); c >= 0; c = pointhedgenext(0, c)) {
        if (hedge_nextequiv(0, c) == c) {
            nxt = c;
            break;
        }
    }
    h = nxt == start ? -1 : nxt;
}
addprim(0, "poly", loop);

float total = 0;
int v = pointvertex(0, @ptnum);
while (v >= 0) {
    int pr = vertexprim(0, v);
    int idx = vertexprimindex(0, v);
    int n = primvertexcount(0, pr);
    int prevpt = vertexpoint(0, vertexindex(0, pr, (idx + n - 1) % n));
    int nextpt = vertexpoint(0, vertexindex(0, pr, (idx + 1) % n));
    vector a = normalize(point(0, "P", prevpt) - @P);
    vector b = normalize(point(0, "P", nextpt) - @P);
    total += degrees(acos(clamp(dot(a, b), -1, 1)));
    v = vertexnext(0, v);
}
