for (int i = 0; i < nv; i++) {
    int h = vertexhedge(0, vertexindex(0, @primnum, i));
    int other = hedge_nextequiv(0, h);
    if (other == h) continue;
    vector n1 = prim_normal(0, hedge_prim(0, other), 0.5, 0.5);
    float ang = degrees(acos(clamp(dot(n0, n1), -1, 1)));
