float k = chf("curv");
float a = @P.x * k;
float r = 1.0 / k - @P.y;
@P.x = r * sin(a);
@P.y = 1.0 / k - r * cos(a);

float d = distance(@P, chv("center"));
float phase = d / chf("wl") - chf("speed") * @Time;
@P.y += chf("amp") * sin(2 * PI * phase) * exp(-chf("decay") * d);

vector c = curlnoise2d(set(@P.x * chf("freq"), @P.z * chf("freq"), @Time * chf("speed")));
v@v = set(c.x, 0, c.y) * chf("amp");
f@spd = length(v@v);

float t = smooth(chf("y0"), chf("y1"), @P.y);
matrix3 m = ident();
rotate(m, radians(chf("deg")) * t, {0, 1, 0});
@P *= m;

float t = relbbox(0, @P).y;
float s = chramp("profile", t);
@P.x *= s;
@P.z *= s;

vector target = set(chf("r") * cos(chf("w") * @Time), chf("h"), chf("r") * sin(chf("w") * @Time));
matrix3 m = lookat(@P, target, {0, 1, 0});
p@orient = quaternion(m);

vector pv = chv("pivot");
float a = radians(chf("amp")) * cos(2 * PI * @Time / chf("period"));
matrix3 m = ident();
rotate(m, a, {0, 0, 1});
@P = pv + (@P - pv) * m;
f@swing = degrees(a);

float t = max(@Time - 0.15 * relbbox(0, @P).x, 0);
f@ease = 1 - exp(-chf("damp") * t) * cos(chf("freq") * t);
@P.y += chf("height") * f@ease;

float d1 = distance(@P, chv("a"));
float d2 = distance(@P, chv("b"));
float k = chf("k");
float h = clamp(0.5 + 0.5 * (d2 - d1) / k, 0, 1);
float d = lerp(d2, d1, h) - k * h * (1 - h);
f@d = d;
@P.y += chf("amp") * exp(-d * d);

vector c = (getbbox_min(0) + getbbox_max(0)) * 0.5;
float s = chf("s");
vector d = @P - c;
@P = c + set(d.x / sqrt(s), d.y * s, d.z / sqrt(s));

float t = relbbox(0, @P).y;
v@Cd = chramp("grad", t);
f@lum = luminance(v@Cd);

vector4 qa = quaternion(radians(chf("a0")), {0, 1, 0});
vector4 qb = quaternion(radians(chf("a1")), {1, 0, 0});
p@orient = slerp(qa, qb, smooth(0, chf("dur"), @Time));

vector sep = 0;
int crowd = 0;
foreach (int n; nearpoints(0, @P, chf("radius"))) {
    if (n == @ptnum) continue;
    vector d = @P - point(0, "P", n);
    float dist = length(d);
    sep += d / dist * (1 - dist / chf("radius"));
    crowd++;
}
v@sep = sep * chf("strength");
i@crowd = crowd;

int h = pcopen(0, "P", @P, chf("radius"), 100);
vector sumv = 0;
vector sump = 0;
int cnt = 0;
while (pciterate(h)) {
    int pn;
    vector p;
    vector vel;
    pcimport(h, "point.number", pn);
    if (pn == @ptnum) continue;
    pcimport(h, "P", p);
    pcimport(h, "v", vel);
    sumv += vel;
    sump += p;
    cnt++;
}
pcclose(h);
vector steer = 0;
if (cnt > 0)
    steer = chf("align") * (sumv / cnt - @v) + chf("cohere") * (sump / cnt - @P);
v@steer = steer;
i@nbrs = cnt;

vector t = normalize(chv("target") - @P);
float speed = length(@v);
vector dir = normalize(@v);
float ang = acos(clamp(dot(dir, t), -1, 1));
float maxang = radians(chf("maxturn")) * chf("dt");
vector newdir = t;
if (ang > maxang) {
    vector4 q = dihedral(dir, t);
    q = slerp({0, 0, 0, 1}, q, maxang / ang);
    newdir = qrotate(q, dir);
}
v@v = newdir * speed;
f@turned = degrees(min(ang, maxang));

vector acc = {0, -1, 0} * chf("g") - chf("drag") * length(@v) * @v / @mass;
@v += acc * @TimeInc;
@P += @v * @TimeInc;

vector lo = chv("bmin");
vector hi = chv("bmax");
float e = chf("restitution");
int hits = 0;
for (int i = 0; i < 3; i++) {
    if (@P[i] < lo[i]) {
        @P[i] = lo[i];
        @v[i] = e * abs(@v[i]);
        hits++;
    } else if (@P[i] > hi[i]) {
        @P[i] = hi[i];
        @v[i] = -e * abs(@v[i]);
        hits++;
    }
}
i@hits = hits;

float dt = chf("dt");
vector v1 = volumesamplev(1, "vel", @P);
vector mid = @P + 0.5 * dt * v1;
vector v2 = volumesamplev(1, "vel", mid);
@P += v2 * dt;
@v = v2;

